source('R/stile.R')
d<-leggi('campioni_modulo1.csv');d$alterazione<-factor(d$alterazione,levels=c('bassa','media','alta'),ordered=TRUE);d$densita<-d$massa_g/d$volume_cm3
verifica('24 provini e sei stazioni',nrow(d)==24 && length(unique(d$stazione))==6)
verifica('densita C01',abs(d$densita[1]-2.68)<1e-12)
p<-ggplot(d,aes(volume_cm3,massa_g,colour=affioramento))+geom_abline(slope=c(2.4,2.8),intercept=0,colour='#657180',linetype=2)+geom_point(size=3.4)+scale_colour_manual(values=geo)+labs(x='Volume (cm³)',y='Massa (g)')
salva('M01','F01',p)
st<-aggregate(densita~stazione+affioramento,d,mean)
p<-ggplot(d,aes(stazione,densita,colour=affioramento))+geom_point(position=position_jitter(width=.1,height=0,seed=1),size=3)+geom_point(data=st,shape=18,size=5)+scale_colour_manual(values=geo)+scale_y_continuous(labels=fmt)+labs(x='Stazione',y='Densità (g/cm³)')
salva('M01','F02',p)
a<-data.frame(unita=c('g/cm³','kg/m³'),valore=c(2.68,2680))
verifica('conversione unita',a$valore[2]==1000*a$valore[1])
p<-ggplot(a,aes(unita,valore,fill=unita))+geom_col(width=.6)+facet_wrap(~unita,scales='free')+scale_fill_manual(values=geo)+labs(x=NULL,y='Valore numerico')+theme(legend.position='none',axis.text.x=element_blank())
salva('M01','F03',p)
set.seed(501);pop<-data.frame(x=seq(0,1,length.out=500));pop$rho<-2.5+.3*pop$x+rnorm(500,0,.04)
sel<-seq_len(100);srs<-sample(500,100)
p<-ggplot(pop,aes(x,rho))+geom_point(colour=geo[1],alpha=.4,size=1.4)+geom_point(data=pop[sel,],colour=geo[2],size=2)+labs(x='Posizione relativa',y='Densità simulata')
salva('M01','F04',p)
set.seed(502);a<-expand.grid(provino=factor(1:4),replica=1:10);a$misura<-rep(c(2.5,2.6,2.7,2.8),10)+rnorm(40,0,.006)
p<-ggplot(a,aes(provino,misura))+geom_point(colour=geo[1],position=position_jitter(width=.12,height=0,seed=2),size=2.8)+labs(x='Provino',y='Densità misurata')
salva('M01','F05',p)
p<-ggplot(d,aes(alterazione,densita,colour=affioramento))+geom_point(position=position_jitter(width=.12,height=0,seed=3),size=3)+scale_colour_manual(values=geo)+scale_y_continuous(labels=fmt)+labs(x='Alterazione',y='Densità (g/cm³)')
salva('M01','F06',p)
a<-data.frame(soglia=seq(35,49,1));a$n<-sapply(a$soglia,function(v)sum(d$volume_cm3>=v));a$media<-sapply(a$soglia,function(v)mean(d$densita[d$volume_cm3>=v]))
p<-ggplot(a,aes(soglia,media))+geom_line(colour=geo[1],linewidth=1)+geom_point(size=2.5,colour=geo[1])+scale_y_continuous(labels=fmt)+labs(x='Volume minimo (cm³)',y='Densità media (g/cm³)')
salva('M01','F07',p)
a<-data.frame(caso=factor(c('Osservato','Censurato','Mancante'),levels=c('Osservato','Censurato','Mancante')),valore=c(.12,.025,NA),limite=c(.12,.05,NA))
p<-ggplot(a,aes(caso,valore))+geom_point(data=a[1,],size=4,colour=geo[1])+geom_linerange(data=a[2,],aes(ymin=0,ymax=.05),linewidth=2,colour=geo[2])+geom_point(data=a[2,],aes(y=limite),shape=21,fill=paper,colour=geo[2],size=3.5,stroke=1)+annotate('text',x=3,y=.08,label='NA',size=8,colour=ink)+scale_x_discrete(drop=FALSE,labels=c('Misura','Censura','Assente'))+scale_y_continuous(labels=fmt,limits=c(0,.15))+labs(x=NULL,y='Concentrazione')
salva('M01','F08',p)
p<-ggplot(d,aes(affioramento,densita,colour=affioramento))+geom_point(position=position_jitter(width=.13,height=0,seed=4),size=3)+stat_summary(fun=mean,geom='point',shape=18,size=6)+scale_colour_manual(values=geo)+scale_y_continuous(labels=fmt)+labs(x='Affioramento',y='Densità (g/cm³)')+theme(legend.position='none')
salva('M01','F09',p)
set.seed(503);B<-2000;a<-data.frame(disegno=rep(c('Casuale','Accessibile'),each=B),media=c(replicate(B,mean(pop$rho[sample(500,24)])),replicate(B,mean(pop$rho[sample(sel,24)]))))
p<-ggplot(a,aes(media,fill=disegno))+geom_density(alpha=.35)+geom_vline(xintercept=mean(pop$rho),linetype=2)+scale_fill_manual(values=geo)+scale_x_continuous(labels=fmt)+labs(x='Densità media (g/cm³)',y='Densità di probabilità')
salva('M01','F10',p)
verifica('densita invarianti rispetto alla scala',all(abs((d$massa_g/1000)/(d$volume_cm3/1e6)-1000*d$densita)<1e-8))
write.csv(st,'verifiche/M01_medie_stazioni.csv',row.names=FALSE)
